tool_schemas.implementation:
def get_youtube_transcript(video_url=None, youtube_video_id=None, language=None, include_segments=None, refresh=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0489000" if __import__("os").path.isdir("./environment_mix/0489000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    _CROCK = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid():
        ms = int(time.time() * 1000)
        rnd = int.from_bytes(os.urandom(10), "big")
        v = (ms << 80) | rnd
        out = []
        for _ in range(26):
            out.append(_CROCK[v & 31])
            v >>= 5
        return "".join(reversed(out))

    def _extract_video_id(url):
        if not isinstance(url, str) or not url.strip():
            return None
        u = url.strip()
        # Be permissive: if it contains a recognizable YouTube ID in common URL patterns, accept.
        m = re.search(r"(?:youtu\.be/|youtube\.com/(?:watch\?.*v=|embed/|shorts/)|/watch\?.*v=|v=)([A-Za-z0-9_-]{11})", u)
        if m:
            return m.group(1)
        return None

    def _looks_like_video_id(v):
        return isinstance(v, str) and re.fullmatch(r"[A-Za-z0-9_-]{11}", v.strip()) is not None

    def _select_active_key_or_unauthorized(api_keys, now):
        # Ambient auth: choose any active key that can still make calls (or is unlimited).
        candidates = []
        for k in api_keys:
            if k.get("status") != "active":
                continue
            limit = k.get("daily_request_limit")
            used = k.get("daily_request_count")
            if not isinstance(limit, int) or limit < 0:
                continue
            if not isinstance(used, int) or used < 0:
                continue
            ws = _parse_dt(k.get("daily_window_start_at"))
            # If window missing/invalid, treat as resettable.
            if ws is None or ws.astimezone(datetime.timezone.utc).date() != now.date():
                candidates.append((0, k))
                continue
            if limit == 0:
                candidates.append((1, k))
                continue
            if used < limit:
                candidates.append((2, k))
                continue
        if not candidates:
            return None
        candidates.sort(key=lambda x: x[0], reverse=True)
        return candidates[0][1]

    def _apply_quota_or_reject(k, api_keys_rows, now):
        ws = _parse_dt(k.get("daily_window_start_at"))
        if ws is None or ws.astimezone(datetime.timezone.utc).date() != now.date():
            k["daily_window_start_at"] = _iso(datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc))
            k["daily_request_count"] = 0
            ws = _parse_dt(k.get("daily_window_start_at"))

        limit = k.get("daily_request_limit")
        used = k.get("daily_request_count")
        if not isinstance(limit, int) or limit < 0:
            return _err("VALIDATION_ERROR", "API key row has invalid daily_request_limit")
        if not isinstance(used, int) or used < 0:
            return _err("VALIDATION_ERROR", "API key row has invalid daily_request_count")

        if limit > 0 and used + 1 > limit:
            return _err("QUOTA_EXCEEDED", "Daily request limit exceeded", daily_request_limit=limit, daily_request_count=used)
        k["daily_request_count"] = used + 1
        k["last_used_at"] = _iso(now)
        k["updated_at"] = _iso(now)
        return None

    def _append_tool_request(tool_requests, api_key_id, tool_name, status, input_obj, started_at, finished_at, **fields):
        row = {
            "id": "ytins_req_" + _ulid(),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "status": status,
            "input": input_obj if isinstance(input_obj, dict) else {},
            "resolved_youtube_video_id": fields.get("resolved_youtube_video_id"),
            "resolved_youtube_channel_id": fields.get("resolved_youtube_channel_id"),
            "video_id": fields.get("video_id"),
            "channel_id": fields.get("channel_id"),
            "output": fields.get("output"),
            "error_message": fields.get("error_message"),
            "upstream_provider": fields.get("upstream_provider"),
            "started_at": _iso(started_at) if started_at else None,
            "finished_at": _iso(finished_at) if finished_at else None,
            "created_at": _iso(_utcnow()),
            "updated_at": _iso(_utcnow()),
        }
        tool_requests.append(row)
        return row

    t0 = time.time()
    now = _utcnow()

    # Validate inputs (but be permissive about bad video_url if youtube_video_id is present)
    if include_segments is None:
        include_segments = False
    if refresh is None:
        refresh = False
    if include_segments is not None and not isinstance(include_segments, bool):
        return _err("VALIDATION_ERROR", "include_segments must be a boolean")
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean")
    if language is not None and not isinstance(language, str):
        return _err("VALIDATION_ERROR", "language must be a string")

    resolved_from_url = _extract_video_id(video_url) if video_url is not None else None
    resolved_from_id = youtube_video_id.strip() if isinstance(youtube_video_id, str) else youtube_video_id

    if video_url is None and youtube_video_id is None:
        return _err("VALIDATION_ERROR", "Either youtube_video_id or video_url must be provided")
    if youtube_video_id is not None and not _looks_like_video_id(resolved_from_id or ""):
        return _err("VALIDATION_ERROR", "youtube_video_id is not a valid YouTube video id (expected 11 chars)")
    # If both are provided and url has an extractable id, they must agree. If url is not a video URL, ignore it.
    if youtube_video_id is not None and resolved_from_url is not None and resolved_from_url != resolved_from_id:
        return _err("VALIDATION_ERROR", "video_url and youtube_video_id disagree", extracted_video_id=resolved_from_url)

    resolved_youtube_video_id = resolved_from_id if youtube_video_id is not None else resolved_from_url
    if resolved_youtube_video_id is None:
        # URL couldn't be parsed and no explicit id was provided.
        return _err("VALIDATION_ERROR", "Could not resolve youtube_video_id from input (provide youtube_video_id or a valid YouTube video URL)")

    api_keys = _load("api_keys.json")
    videos = _load("videos.json")
    transcripts = _load("transcripts.json")
    tool_requests = _load("tool_requests.json")

    api_key = _select_active_key_or_unauthorized(api_keys, now)
    if api_key is None:
        # Still must log attempt? Business rules say "Every tool invocation must create" but also "Requests must be rejected if key not active".
        # With ambient auth, if none active exists, we cannot create a valid FK row.
        return _err("UNAUTHORIZED", "No active API key available to serve this request")

    # Create request row early (queued->running)
    req_input = {
        "video_url": video_url,
        "youtube_video_id": youtube_video_id,
        "language": language,
        "include_segments": include_segments,
        "refresh": refresh,
    }
    started_at = _utcnow()
    req_row = _append_tool_request(
        tool_requests,
        api_key_id=api_key["id"],
        tool_name="get_youtube_transcript",
        status="running",
        input_obj=req_input,
        started_at=started_at,
        finished_at=None,
        resolved_youtube_video_id=resolved_youtube_video_id,
        upstream_provider="other",
    )
    _save("tool_requests.json", tool_requests)

    # Enforce key active + quota (counts only on accepted invocation; treat "running" as accepted and ensure quota before doing work)
    if api_key.get("status") != "active":
        req_row["status"] = "failed"
        req_row["error_message"] = "API key is not active"
        req_row["finished_at"] = _iso(_utcnow())
        req_row["updated_at"] = _iso(_utcnow())
        _save("tool_requests.json", tool_requests)
        return _err("UNAUTHORIZED", "API key is not active")

    qerr = _apply_quota_or_reject(api_key, api_keys, now)
    if qerr:
        req_row["status"] = "failed"
        req_row["error_message"] = qerr["error"]["message"]
        req_row["finished_at"] = _iso(_utcnow())
        req_row["updated_at"] = _iso(_utcnow())
        _save("tool_requests.json", tool_requests)
        _save("api_keys.json", api_keys)
        return qerr
    _save("api_keys.json", api_keys)

    # Upsert video by youtube_video_id
    vid_row = None
    for v in videos:
        if v.get("youtube_video_id") == resolved_youtube_video_id:
            vid_row = v
            break
    if vid_row is None:
        vid_row = {
            "id": "ytins_vid_" + _ulid(),
            "youtube_video_id": resolved_youtube_video_id,
            "channel_id": None,
            "title": None,
            "description": None,
            "published_at": None,
            "duration_seconds": None,
            "view_count": None,
            "like_count": None,
            "comment_count": None,
            "thumbnail_url": None,
            "language": None,
            "fetched_at": None,
            "created_at": _iso(_utcnow()),
            "updated_at": _iso(_utcnow()),
        }
        videos.append(vid_row)
        _save("videos.json", videos)
    else:
        vid_row["updated_at"] = _iso(_utcnow())
        _save("videos.json", videos)

    req_row["video_id"] = vid_row["id"]
    req_row["updated_at"] = _iso(_utcnow())
    _save("tool_requests.json", tool_requests)

    # Determine desired transcript key fields
    lang = language.strip() if isinstance(language, str) and language.strip() else None

    # If language not provided, pick best available cached transcript for this video
    candidates = [t for t in transcripts if t.get("video_id") == vid_row["id"]]
    chosen = None
    if lang is None:
        # Prefer available then fetching then others; deterministic by updated_at desc
        def _rank(t):
            st = t.get("status")
            return {"available": 3, "fetching": 2, "unavailable": 1, "error": 0}.get(st, -1)
        candidates_sorted = sorted(
            candidates,
            key=lambda t: (_rank(t), _parse_dt(t.get("updated_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)),
            reverse=True,
        )
        chosen = candidates_sorted[0] if candidates_sorted else None
        if chosen is not None:
            lang = chosen.get("language") or "en"
        else:
            lang = "en"

    # Find transcript by uniqueness key (video_id, language, is_auto_generated, source).
    # Since tool doesn't expose is_auto_generated/source, choose a best one:
    # Prefer youtube/manual_upload/third_party in that order, and human over auto.
    def _pref_order(t):
        src = t.get("source")
        is_auto = bool(t.get("is_auto_generated"))
        src_rank = {"youtube": 3, "manual_upload": 2, "third_party": 1}.get(src, 0)
        auto_rank = 0 if is_auto else 1
        st_rank = {"available": 3, "fetching": 2, "unavailable": 1, "error": 0}.get(t.get("status"), -1)
        upd = _parse_dt(t.get("updated_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (st_rank, src_rank, auto_rank, upd)

    key_matches = [t for t in candidates if (t.get("language") == lang)]
    if key_matches:
        tr_row = sorted(key_matches, key=_pref_order, reverse=True)[0]
    else:
        tr_row = None

    # Cache TTL for available transcripts
    TTL_SECONDS = 7 * 24 * 3600
    def _is_fresh_available(trow):
        if trow is None:
            return False
        if trow.get("status") != "available":
            return False
        fetched = _parse_dt(trow.get("fetched_at")) or _parse_dt(trow.get("updated_at"))
        if fetched is None:
            return False
        return (now - fetched).total_seconds() <= TTL_SECONDS

    # Serve cache unless refresh requested
    if not refresh and _is_fresh_available(tr_row):
        out = {
            "youtube_video_id": resolved_youtube_video_id,
            "video_id": vid_row["id"],
            "language": tr_row.get("language"),
            "is_auto_generated": bool(tr_row.get("is_auto_generated")),
            "source": tr_row.get("source"),
            "status": tr_row.get("status"),
            "transcript_text": tr_row.get("transcript_text"),
            "segments": tr_row.get("segments") if include_segments else None,
            "fetched_at": tr_row.get("fetched_at"),
        }
        req_row["status"] = "succeeded"
        req_row["output"] = out
        req_row["finished_at"] = _iso(_utcnow())
        req_row["updated_at"] = _iso(_utcnow())
        _save("tool_requests.json", tool_requests)
        return {"data": out, "meta": {"cached": True, "latency_ms": int((time.time() - t0) * 1000)}}

    # Need to (re)fetch: ensure transcript row exists and set to fetching via legal transitions.
    # If no row exists, create one in fetching.
    if tr_row is None:
        tr_row = {
            "id": "ytins_trn_" + _ulid(),
            "video_id": vid_row["id"],
            "language": lang,
            "is_auto_generated": True,   # default when unknown
            "status": "fetching",
            "transcript_text": None,
            "segments": None,
            "source": "youtube",         # default
            "error_code": None,
            "error_message": None,
            "fetched_at": None,
            "created_at": _iso(_utcnow()),
            "updated_at": _iso(_utcnow()),
        }
        transcripts.append(tr_row)
        _save("transcripts.json", transcripts)
    else:
        if tr_row.get("status") == "fetching":
            # If refresh requested and already fetching: treat as conflict
            if refresh:
                req_row["status"] = "failed"
                req_row["error_message"] = "Transcript is already being fetched"
                req_row["finished_at"] = _iso(_utcnow())
                req_row["updated_at"] = _iso(_utcnow())
                _save("tool_requests.json", tool_requests)
                return _err("CONFLICT", "Transcript is already in fetching state")
        else:
            # Legal transition is only *to* fetching from available/unavailable/error
            tr_row["status"] = "fetching"
            tr_row["updated_at"] = _iso(_utcnow())
            _save("transcripts.json", transcripts)

    # Offline backend: we cannot actually call upstream; simulate a queued fetch and return current row.
    out = {
        "youtube_video_id": resolved_youtube_video_id,
        "video_id": vid_row["id"],
        "language": tr_row.get("language"),
        "is_auto_generated": bool(tr_row.get("is_auto_generated")),
        "source": tr_row.get("source"),
        "status": tr_row.get("status"),
        "transcript_text": tr_row.get("transcript_text"),
        "segments": tr_row.get("segments") if include_segments else None,
        "fetched_at": tr_row.get("fetched_at"),
    }
    req_row["status"] = "succeeded"
    req_row["output"] = out
    req_row["finished_at"] = _iso(_utcnow())
    req_row["updated_at"] = _iso(_utcnow())
    _save("tool_requests.json", tool_requests)
    return {"data": out, "meta": {"cached": False, "latency_ms": int((time.time() - t0) * 1000)}}

def search_youtube_videos(query, limit=None, cursor=None, order_by=None, published_after=None, published_before=None, channel_id=None, language=None, region_code=None, safe_search=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0489000" if __import__("os").path.isdir("./environment_mix/0489000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _ulid():
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        rnd = int.from_bytes(os.urandom(10), "big")
        v = (ms << 80) | rnd
        out = []
        for _ in range(26):
            out.append(alphabet[v & 31])
            v >>= 5
        return "".join(reversed(out))

    def _b32e(b):
        return base64.b32encode(b).decode("ascii").rstrip("=")

    def _select_api_key_for_call():
        keys = _load("api_keys.json")
        now = _now()
        for k in keys:
            if k.get("status") != "active":
                continue
            limit = k.get("daily_request_limit")
            cnt = k.get("daily_request_count")
            ws = _parse_dt(k.get("daily_window_start_at"))
            if not isinstance(limit, int) or limit < 0:
                continue
            if not isinstance(cnt, int) or cnt < 0:
                continue
            if ws is None:
                return k
            if ws.tzinfo is None:
                ws = ws.replace(tzinfo=datetime.timezone.utc)
            if now.date() != ws.astimezone(datetime.timezone.utc).date():
                return k
            if limit == 0 or cnt < limit:
                return k
        return None

    def _enforce_and_increment_quota(api_key_row):
        keys = _load("api_keys.json")
        now = _now()
        kid = api_key_row.get("id")
        idx = next((i for i, r in enumerate(keys) if r.get("id") == kid), None)
        if idx is None:
            return None, _err("UNAUTHORIZED", "No API key context available.")
        row = keys[idx]
        if row.get("status") != "active":
            return None, _err("UNAUTHORIZED", "API key is not active.")
        limit = row.get("daily_request_limit")
        cnt = row.get("daily_request_count")
        ws = _parse_dt(row.get("daily_window_start_at"))
        if not isinstance(limit, int) or limit < 0:
            return None, _err("VALIDATION_ERROR", "API key daily_request_limit is invalid.")
        if not isinstance(cnt, int) or cnt < 0:
            return None, _err("VALIDATION_ERROR", "API key daily_request_count is invalid.")
        if ws is None or ws.tzinfo is None:
            ws = now
        ws_utc = ws.astimezone(datetime.timezone.utc)
        if now.date() != ws_utc.date():
            row["daily_window_start_at"] = _iso(datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc))
            row["daily_request_count"] = 0
            cnt = 0
        if limit > 0 and cnt + 1 > limit:
            return None, _err("QUOTA_EXCEEDED", "Daily request limit exceeded.", daily_request_limit=limit)
        row["daily_request_count"] = cnt + 1
        row["last_used_at"] = _iso(now)
        row["updated_at"] = _iso(now)
        keys[idx] = row
        _save("api_keys.json", keys)
        return row, None

    def _log_tool_request(api_key_id, tool_name, status, input_obj, resolved_youtube_video_id=None, resolved_youtube_channel_id=None, video_id=None, channel_id=None, output=None, error_message=None, upstream_provider=None, started_at=None, finished_at=None):
        trs = _load("tool_requests.json")
        now = _now()
        tid = _ulid()
        row = {
            "id": tid,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "status": status,
            "input": input_obj if isinstance(input_obj, dict) else {},
            "resolved_youtube_video_id": resolved_youtube_video_id,
            "resolved_youtube_channel_id": resolved_youtube_channel_id,
            "video_id": video_id,
            "channel_id": channel_id,
            "output": output,
            "error_message": error_message,
            "upstream_provider": upstream_provider,
            "started_at": _iso(started_at),
            "finished_at": _iso(finished_at),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        trs.append(row)
        _save("tool_requests.json", trs)
        return row

    t0 = time.time()
    # Validate
    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "query must be a non-empty string.")
    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 50:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if order_by is None:
        order_by = "relevance"
    if order_by not in ("relevance", "date", "view_count", "rating"):
        return _err("VALIDATION_ERROR", "order_by is invalid.")
    if safe_search is None:
        safe_search = "moderate"
    if safe_search not in ("none", "moderate", "strict"):
        return _err("VALIDATION_ERROR", "safe_search is invalid.")
    if published_after is not None and _parse_dt(published_after) is None:
        return _err("VALIDATION_ERROR", "published_after must be an ISO-8601 date-time.")
    if published_before is not None and _parse_dt(published_before) is None:
        return _err("VALIDATION_ERROR", "published_before must be an ISO-8601 date-time.")
    if channel_id is not None and (not isinstance(channel_id, str) or not channel_id.strip()):
        return _err("VALIDATION_ERROR", "channel_id must be a string.")
    if language is not None and (not isinstance(language, str) or not language.strip()):
        return _err("VALIDATION_ERROR", "language must be a string.")
    if region_code is not None and (not isinstance(region_code, str) or not re.fullmatch(r"[A-Za-z]{2}", region_code.strip())):
        return _err("VALIDATION_ERROR", "region_code must be a 2-letter country code.")
    region_code = region_code.strip().upper() if isinstance(region_code, str) else None

    # cursor decoding
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if obj.get("q") != query or obj.get("o") != order_by:
                return _err("VALIDATION_ERROR", "cursor does not match this query/order_by.")
            offset = int(obj.get("offset", 0))
            if offset < 0:
                return _err("VALIDATION_ERROR", "cursor is invalid.")
        except (ValueError, json.JSONDecodeError):
            return _err("VALIDATION_ERROR", "cursor is invalid.")

    api_key = _select_api_key_for_call()
    if not api_key:
        return _err("UNAUTHORIZED", "No active API key available to authorize this request.")

    # quota pre-check
    keys_all = _load("api_keys.json")
    now = _now()
    ak_row = next((k for k in keys_all if k.get("id") == api_key.get("id")), None)
    if not ak_row or ak_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active.")
    limit_q = ak_row.get("daily_request_limit")
    cnt_q = ak_row.get("daily_request_count")
    ws = _parse_dt(ak_row.get("daily_window_start_at"))
    if not isinstance(limit_q, int) or limit_q < 0 or not isinstance(cnt_q, int) or cnt_q < 0:
        return _err("VALIDATION_ERROR", "API key quota configuration invalid.")
    if ws is None or ws.tzinfo is None:
        ws = now
    if now.date() != ws.astimezone(datetime.timezone.utc).date():
        cnt_effective = 0
    else:
        cnt_effective = cnt_q
    if limit_q > 0 and cnt_effective + 1 > limit_q:
        _log_tool_request(
            api_key_id=api_key["id"],
            tool_name="search_youtube_videos",
            status="failed",
            input_obj={"query": query, "limit": limit, "cursor": cursor, "order_by": order_by, "published_after": published_after, "published_before": published_before, "channel_id": channel_id, "language": language, "region_code": region_code, "safe_search": safe_search},
            error_message="Daily request limit exceeded.",
            upstream_provider=None,
            finished_at=_now(),
        )
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded.", daily_request_limit=limit_q)

    tr = _log_tool_request(
        api_key_id=api_key["id"],
        tool_name="search_youtube_videos",
        status="running",
        input_obj={"query": query, "limit": limit, "cursor": cursor, "order_by": order_by, "published_after": published_after, "published_before": published_before, "channel_id": channel_id, "language": language, "region_code": region_code, "safe_search": safe_search},
        upstream_provider="other",
        started_at=_now(),
    )

    _, qerr = _enforce_and_increment_quota(api_key)
    if qerr:
        trs = _load("tool_requests.json")
        for r in trs:
            if r.get("id") == tr["id"]:
                r["status"] = "failed"
                r["error_message"] = qerr["error"]["message"]
                r["finished_at"] = _iso(_now())
                r["updated_at"] = _iso(_now())
                break
        _save("tool_requests.json", trs)
        return qerr

    # Simulate search results deterministically (offline)
    seed = hashlib.sha256((query.strip().lower() + "|" + order_by + "|" + safe_search + "|" + (channel_id or "") + "|" + (language or "") + "|" + (region_code or "")).encode("utf-8")).digest()
    total = 250  # fixed simulated total
    if offset >= total:
        items = []
    else:
        n = min(limit, total - offset)
        items = []
        for i in range(n):
            k = offset + i
            # deterministic ids
            vid = _b32e(hashlib.sha1(seed + str(k).encode("utf-8")).digest())[:11]
            ycid = "UC" + _b32e(hashlib.md5(seed + b"ch" + str(k).encode("utf-8")).digest())[:22]
            if channel_id:
                ycid = channel_id.strip()
            published = _now() - datetime.timedelta(days=(k % 365), hours=(k % 24))
            # apply published filters
            pa = _parse_dt(published_after) if published_after else None
            pb = _parse_dt(published_before) if published_before else None
            if pa and published < (pa if pa.tzinfo else pa.replace(tzinfo=datetime.timezone.utc)):
                continue
            if pb and published > (pb if pb.tzinfo else pb.replace(tzinfo=datetime.timezone.utc)):
                continue
            items.append({
                "youtube_video_id": vid,
                "youtube_channel_id": ycid,
                "title": f"{query.strip()} - Result {k+1}",
                "published_at": _iso(published),
                "thumbnail_url": f"https://i.ytimg.com/vi/{vid}/hqdefault.jpg",
                "view_count": int.from_bytes(hashlib.sha1(seed + b"v" + str(k).encode("utf-8")).digest()[:4], "big") % 5_000_000,
                "like_count": int.from_bytes(hashlib.sha1(seed + b"l" + str(k).encode("utf-8")).digest()[:4], "big") % 200_000,
                "comment_count": int.from_bytes(hashlib.sha1(seed + b"c" + str(k).encode("utf-8")).digest()[:4], "big") % 50_000,
                "channel_title": f"Channel {ycid[-6:]}",
                "language": (language.strip() if isinstance(language, str) and language.strip() else None),
                "region_code": region_code,
            })

    # Upsert channels/videos for returned results
    channels = _load("channels.json")
    videos = _load("videos.json")

    def _find_channel_by_ycid(ycid):
        return next((c for c in channels if c.get("youtube_channel_id") == ycid), None)

    def _find_video_by_yvid(yvid):
        return next((v for v in videos if v.get("youtube_video_id") == yvid), None)

    now = _now()
    upserted_video_ids = []
    for it in items:
        yvid = it.get("youtube_video_id")
        ycid = it.get("youtube_channel_id")
        ch_row = None
        if isinstance(ycid, str) and ycid:
            ch_row = _find_channel_by_ycid(ycid)
            if ch_row is None:
                ch_row = {
                    "id": _ulid(),
                    "youtube_channel_id": ycid,
                    "handle": None,
                    "title": it.get("channel_title"),
                    "description": None,
                    "country": region_code,
                    "subscriber_count": None,
                    "video_count": None,
                    "view_count": None,
                    "thumbnail_url": None,
                    "fetched_at": None,
                    "created_at": _iso(now),
                    "updated_at": _iso(now),
                }
                channels.append(ch_row)
            else:
                # update non-null basics
                if it.get("channel_title") and not ch_row.get("title"):
                    ch_row["title"] = it.get("channel_title")
                ch_row["updated_at"] = _iso(now)
        # upsert video
        if isinstance(yvid, str) and yvid:
            vrow = _find_video_by_yvid(yvid)
            if vrow is None:
                vrow = {
                    "id": _ulid(),
                    "youtube_video_id": yvid,
                    "channel_id": ch_row.get("id") if ch_row else None,
                    "title": it.get("title"),
                    "description": None,
                    "published_at": it.get("published_at"),
                    "duration_seconds": None,
                    "view_count": it.get("view_count"),
                    "like_count": it.get("like_count"),
                    "comment_count": it.get("comment_count"),
                    "thumbnail_url": it.get("thumbnail_url"),
                    "language": it.get("language"),
                    "fetched_at": None,
                    "created_at": _iso(now),
                    "updated_at": _iso(now),
                }
                videos.append(vrow)
            else:
                # FK integrity: only set channel_id if channel exists
                if ch_row and (vrow.get("channel_id") is None):
                    vrow["channel_id"] = ch_row.get("id")
                if it.get("title"):
                    vrow["title"] = it.get("title")
                vrow["published_at"] = it.get("published_at") or vrow.get("published_at")
                vrow["view_count"] = it.get("view_count") if isinstance(it.get("view_count"), int) else vrow.get("view_count")
                vrow["like_count"] = it.get("like_count") if isinstance(it.get("like_count"), int) else vrow.get("like_count")
                vrow["comment_count"] = it.get("comment_count") if isinstance(it.get("comment_count"), int) else vrow.get("comment_count")
                vrow["thumbnail_url"] = it.get("thumbnail_url") or vrow.get("thumbnail_url")
                vrow["language"] = it.get("language") or vrow.get("language")
                vrow["updated_at"] = _iso(now)
            upserted_video_ids.append(vrow["id"])

    _save("channels.json", channels)
    _save("videos.json", videos)

    next_offset = offset + limit
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = {"q": query, "o": order_by, "offset": next_offset}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload).encode("utf-8")).decode("utf-8").rstrip("=")

    output = {"results": items, "cursor": next_cursor, "limit": limit, "total_estimated": total}
    # update tool_request
    trs = _load("tool_requests.json")
    for r in trs:
        if r.get("id") == tr["id"]:
            r["status"] = "succeeded"
            r["output"] = output
            r["finished_at"] = _iso(_now())
            r["updated_at"] = _iso(_now())
            break
    _save("tool_requests.json", trs)

    return {
        "data": {"results": items, "cursor": next_cursor},
        "meta": {"limit": limit, "has_more": has_more, "next_cursor": next_cursor, "latency_ms": int((time.time() - t0) * 1000)},
    }

def get_channel_info(video_url, recent_videos_limit=None, refresh=None, **_extra):
    import json, os, datetime, time, re, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0489000" if __import__("os").path.isdir("./environment_mix/0489000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    _CROCK = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid():
        ms = int(time.time() * 1000)
        rnd = int.from_bytes(os.urandom(10), "big")
        v = (ms << 80) | rnd
        out = []
        for _ in range(26):
            out.append(_CROCK[v & 31])
            v >>= 5
        return "".join(reversed(out))

    def _new_id(prefix):
        return f"{prefix}_{_ulid()}"

    def _reset_window_if_needed(k, now):
        ws = _parse_dt(k.get("daily_window_start_at"))
        if ws is None or ws.astimezone(datetime.timezone.utc).date() != now.date():
            k["daily_window_start_at"] = _iso(datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc))
            k["daily_request_count"] = 0

    def _select_key_for_call(api_keys, now):
        # Ambient auth: choose any ACTIVE key that can accept this call right now.
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            _reset_window_if_needed(k, now)
            limit = k.get("daily_request_limit")
            count = k.get("daily_request_count", 0)
            if not isinstance(limit, int) or limit < 0:
                continue
            if not isinstance(count, int) or count < 0:
                continue
            if limit != 0 and count + 1 > limit:
                continue
            return k
        return None

    def _extract_video_id_any(url):
        if not isinstance(url, str) or not url.strip():
            return None
        url = url.strip()

        # Allow plain video id
        if re.fullmatch(r"[A-Za-z0-9_-]{6,64}", url):
            return url

        # Parse as URL if possible
        try:
            p = urllib.parse.urlparse(url)
        except Exception:
            return None

        host = (p.netloc or "").lower()
        path = p.path or ""
        qs = urllib.parse.parse_qs(p.query or "")

        # Standard YouTube URLs
        if "youtube.com" in host:
            if path == "/watch" and "v" in qs and qs["v"]:
                return qs["v"][0]
            m = re.match(r"^/shorts/([A-Za-z0-9_-]{6,64})", path)
            if m:
                return m.group(1)
            m = re.match(r"^/embed/([A-Za-z0-9_-]{6,64})", path)
            if m:
                return m.group(1)

        if "youtu.be" in host:
            m = re.match(r"^/([A-Za-z0-9_-]{6,64})", path)
            if m:
                return m.group(1)

        # Relaxed fallback: attempt to find a plausible id anywhere in the string.
        m = re.search(r"(?<![A-Za-z0-9_-])([A-Za-z0-9_-]{6,64})(?![A-Za-z0-9_-])", url)
        if m:
            return m.group(1)

        return None

    t0 = time.time()
    now = _utcnow()

    # Validate inputs
    if not isinstance(video_url, str) or not video_url.strip():
        return _err("VALIDATION_ERROR", "video_url must be a non-empty string")
    if recent_videos_limit is None:
        recent_videos_limit = 10
    if not isinstance(recent_videos_limit, int):
        return _err("VALIDATION_ERROR", "recent_videos_limit must be an integer")
    if recent_videos_limit < 0:
        return _err("VALIDATION_ERROR", "recent_videos_limit must be >= 0")
    if recent_videos_limit > 10:
        # Tool description: up to 10
        recent_videos_limit = 10
    if refresh is None:
        refresh = False
    if not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean")

    api_keys = _load("api_keys.json")
    channels = _load("channels.json")
    videos = _load("videos.json")
    tool_requests = _load("tool_requests.json")

    api_key = _select_key_for_call(api_keys, now)
    if api_key is None:
        # Only UNAUTHORIZED if no active key can serve the call at all.
        return _err("UNAUTHORIZED", "No active API key available for this request")

    youtube_video_id = _extract_video_id_any(video_url)
    if not youtube_video_id:
        # Must be VALIDATION_ERROR for non-video URL
        # Still must create tool_requests row? Business rule says every invocation must create; but rejected calls are not accepted.
        # We'll still audit failed attempt with tool_requests row, without consuming quota (real systems often do). Here quota increments only on accepted.
        req_id = _new_id("ytins_req")
        tr = {
            "id": req_id,
            "api_key_id": api_key.get("id"),
            "tool_name": "get_channel_info",
            "status": "failed",
            "input": {"video_url": video_url, "recent_videos_limit": recent_videos_limit, "refresh": refresh},
            "resolved_youtube_video_id": None,
            "resolved_youtube_channel_id": None,
            "video_id": None,
            "channel_id": None,
            "output": None,
            "error_message": "Could not extract youtube_video_id from video_url",
            "upstream_provider": "other",
            "started_at": _iso(now),
            "finished_at": _iso(_utcnow()),
            "created_at": _iso(now),
            "updated_at": _iso(_utcnow()),
        }
        tool_requests.append(tr)
        _save("tool_requests.json", tool_requests)
        return _err("VALIDATION_ERROR", "video_url is not a valid YouTube video URL", tool_request_id=req_id)

    # Create tool request row early
    req_id = _new_id("ytins_req")
    tr = {
        "id": req_id,
        "api_key_id": api_key.get("id"),
        "tool_name": "get_channel_info",
        "status": "running",
        "input": {"video_url": video_url, "recent_videos_limit": recent_videos_limit, "refresh": refresh},
        "resolved_youtube_video_id": youtube_video_id,
        "resolved_youtube_channel_id": None,
        "video_id": None,
        "channel_id": None,
        "output": None,
        "error_message": None,
        "upstream_provider": "other",
        "started_at": _iso(now),
        "finished_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    tool_requests.append(tr)
    _save("tool_requests.json", tool_requests)

    # Enforce key status and quota for accepted invocations (this one is accepted since inputs validated and request row created)
    if api_key.get("status") != "active":
        tr["status"] = "failed"
        tr["error_message"] = "API key is not active"
        tr["finished_at"] = _iso(_utcnow())
        tr["updated_at"] = tr["finished_at"]
        _save("tool_requests.json", tool_requests)
        return _err("UNAUTHORIZED", "API key is not active", tool_request_id=req_id)

    _reset_window_if_needed(api_key, now)
    limit = api_key.get("daily_request_limit", 0)
    count = api_key.get("daily_request_count", 0)
    if isinstance(limit, int) and limit > 0 and isinstance(count, int) and count + 1 > limit:
        tr["status"] = "failed"
        tr["error_message"] = "Daily request quota exceeded"
        tr["finished_at"] = _iso(_utcnow())
        tr["updated_at"] = tr["finished_at"]
        _save("tool_requests.json", tool_requests)
        _save("api_keys.json", api_keys)  # window reset may have changed
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded", tool_request_id=req_id)

    api_key["daily_request_count"] = int(count) + 1
    api_key["last_used_at"] = _iso(_utcnow())
    api_key["updated_at"] = api_key["last_used_at"]
    _save("api_keys.json", api_keys)

    # Resolve video and channel from local cache (offline behavior): do not require URL to be a youtube.com watch URL.
    video_row = None
    for v in videos:
        if isinstance(v, dict) and v.get("youtube_video_id") == youtube_video_id:
            video_row = v
            break

    if video_row is None:
        tr["status"] = "failed"
        tr["error_message"] = "Video could not be resolved from the provided URL using cached data"
        tr["finished_at"] = _iso(_utcnow())
        tr["updated_at"] = tr["finished_at"]
        tr["resolved_youtube_channel_id"] = None
        _save("tool_requests.json", tool_requests)
        return _err("NOT_FOUND", "Video could not be resolved from the provided URL in offline mode", tool_request_id=req_id, youtube_video_id=youtube_video_id)

    tr["video_id"] = video_row.get("id")
    channel_id = video_row.get("channel_id")

    channel_row = None
    if channel_id:
        for c in channels:
            if isinstance(c, dict) and c.get("id") == channel_id:
                channel_row = c
                break

    # If the video isn't linked to a channel, attempt to infer channel by any existing channel reference (not available offline),
    # so we can only fail.
    if channel_row is None:
        tr["status"] = "failed"
        tr["error_message"] = "Channel could not be resolved from cached video metadata"
        tr["finished_at"] = _iso(_utcnow())
        tr["updated_at"] = tr["finished_at"]
        _save("tool_requests.json", tool_requests)
        return _err("NOT_FOUND", "Channel could not be resolved from the provided URL in offline mode", tool_request_id=req_id, youtube_video_id=youtube_video_id)

    tr["channel_id"] = channel_row.get("id")
    tr["resolved_youtube_channel_id"] = channel_row.get("youtube_channel_id")

    # Refresh behavior: offline cannot refetch; interpret as CONFLICT only if a refresh is requested but cannot be performed.
    if refresh is True:
        tr["status"] = "failed"
        tr["error_message"] = "Refresh requested but upstream refresh is not available in offline mode"
        tr["finished_at"] = _iso(_utcnow())
        tr["updated_at"] = tr["finished_at"]
        _save("tool_requests.json", tool_requests)
        return _err("CONFLICT", "refresh is currently unavailable (offline mode)", tool_request_id=req_id)

    # Gather recent videos from cache for this channel (best-effort ordering by published_at desc)
    channel_videos = [v for v in videos if isinstance(v, dict) and v.get("channel_id") == channel_row.get("id")]

    def _sort_key(v):
        dt = _parse_dt(v.get("published_at"))
        return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    channel_videos.sort(key=_sort_key, reverse=True)
    channel_videos = channel_videos[:recent_videos_limit]

    body = {
        "channel": channel_row,
        "videos": channel_videos,
        "recent_videos_limit": recent_videos_limit,
        "cached": True,
    }

    tr["status"] = "succeeded"
    tr["output"] = body
    tr["finished_at"] = _iso(_utcnow())
    tr["updated_at"] = tr["finished_at"]
    _save("tool_requests.json", tool_requests)

    return {
        "tool_request_id": req_id,
        "channel": channel_row,
        "videos": channel_videos,
        "meta": {
            "recent_videos_limit": recent_videos_limit,
            "cached": True,
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def list_tool_requests(limit=None, cursor=None, status=None, tool_name=None, youtube_video_id=None, youtube_channel_id=None, created_after=None, created_before=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0489000" if __import__("os").path.isdir("./environment_mix/0489000") else "/app/database")
    def _load(n):
