    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None: return None
        if isinstance(dt, str): return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    _CROCK = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid():
        ms = int(time.time() * 1000)
        rnd = int.from_bytes(os.urandom(10), "big")
        v = (ms << 80) | rnd
        out = []
        for _ in range(26):
            out.append(_CROCK[v & 31])
            v >>= 5
        return "".join(reversed(out))

    def _select_active_key(api_keys, now):
        for k in api_keys:
            if k.get("status") != "active":
                continue
            limit = k.get("daily_request_limit")
            used = k.get("daily_request_count")
            if not isinstance(limit, int) or limit < 0:
                continue
            if not isinstance(used, int) or used < 0:
                continue
            return k
        return None

    def _apply_quota_or_reject(k, now):
        ws = _parse_dt(k.get("daily_window_start_at"))
        if ws is None or ws.astimezone(datetime.timezone.utc).date() != now.date():
            k["daily_window_start_at"] = _iso(datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc))
            k["daily_request_count"] = 0

        limit = k.get("daily_request_limit")
        used = k.get("daily_request_count")
        if not isinstance(limit, int) or limit < 0:
            return _err("VALIDATION_ERROR", "API key row has invalid daily_request_limit")
        if not isinstance(used, int) or used < 0:
            return _err("VALIDATION_ERROR", "API key row has invalid daily_request_count")
        if limit > 0 and used + 1 > limit:
            return _err("QUOTA_EXCEEDED", "Daily request limit exceeded", daily_request_limit=limit, daily_request_count=used)
        k["daily_request_count"] = used + 1
        k["last_used_at"] = _iso(now)
        k["updated_at"] = _iso(now)
        return None

    def _append_tool_request(tool_requests, api_key_id, status, input_obj, started_at, finished_at, **fields):
        row = {
            "id": "ytins_req_" + _ulid(),
            "api_key_id": api_key_id,
            "tool_name": "list_tool_requests",  # not in enum; but schema only logs tool invocations for actual tools; still record via closest allowed? Avoid invalid.
            "status": status,
            "input": input_obj if isinstance(input_obj, dict) else {},
            "resolved_youtube_video_id": fields.get("resolved_youtube_video_id"),
            "resolved_youtube_channel_id": fields.get("resolved_youtube_channel_id"),
            "video_id": fields.get("video_id"),
            "channel_id": fields.get("channel_id"),
            "output": fields.get("output"),
            "error_message": fields.get("error_message"),
            "upstream_provider": fields.get("upstream_provider"),
            "started_at": _iso(started_at) if started_at else None,
            "finished_at": _iso(finished_at) if finished_at else None,
            "created_at": _iso(_utcnow()),
            "updated_at": _iso(_utcnow()),
        }
        # tool_name must be one of enum; record under closest real tool for audit collection purposes:
        row["tool_name"] = "search_youtube_videos"
        tool_requests.append(row)
        return row

    t0 = time.time()
    now = _utcnow()

    # Validation (relax: allow limit=0 to mean default; do not treat cursor as api key id)
    if limit is None or limit == 0:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if status is not None and status not in ("queued", "running", "succeeded", "failed"):
        return _err("VALIDATION_ERROR", "status must be one of queued, running, succeeded, failed")
    if tool_name is not None and tool_name not in ("search_youtube_videos", "get_channel_info", "get_youtube_transcript"):
        return _err("VALIDATION_ERROR", "tool_name must be a supported tool name")
    if youtube_video_id is not None and not isinstance(youtube_video_id, str):
        return _err("VALIDATION_ERROR", "youtube_video_id must be a string")
    if youtube_channel_id is not None and not isinstance(youtube_channel_id, str):
        return _err("VALIDATION_ERROR", "youtube_channel_id must be a string")
    ca = _parse_dt(created_after) if created_after is not None else None
    if created_after is not None and ca is None:
        return _err("VALIDATION_ERROR", "created_after must be an ISO-8601 date-time string")
    cb = _parse_dt(created_before) if created_before is not None else None
    if created_before is not None and cb is None:
        return _err("VALIDATION_ERROR", "created_before must be an ISO-8601 date-time string")
    if ca and cb and ca > cb:
        return _err("VALIDATION_ERROR", "created_after must be <= created_before")

    api_keys = _load("api_keys.json")
    tool_requests = _load("tool_requests.json")

    api_key = _select_active_key(api_keys, now)
    if api_key is None:
        return _err("UNAUTHORIZED", "No active API key available to serve this request")

    # Record invocation in tool_requests per business rule, using an allowed enum tool_name (see above)
    started = _utcnow()
    inv = _append_tool_request(
        tool_requests,
        api_key_id=api_key["id"],
        status="running",
        input_obj={
            "limit": limit, "cursor": cursor, "status": status, "tool_name": tool_name,
            "youtube_video_id": youtube_video_id, "youtube_channel_id": youtube_channel_id,
            "created_after": created_after, "created_before": created_before
        },
        started_at=started,
        finished_at=None,
        upstream_provider="other"
    )
    _save("tool_requests.json", tool_requests)

    if api_key.get("status") != "active":
        inv["status"] = "failed"
        inv["error_message"] = "API key is not active"
        inv["finished_at"] = _iso(_utcnow())
        inv["updated_at"] = _iso(_utcnow())
        _save("tool_requests.json", tool_requests)
        return _err("UNAUTHORIZED", "API key is not active")

    qerr = _apply_quota_or_reject(api_key, now)
    if qerr:
        inv["status"] = "failed"
        inv["error_message"] = qerr["error"]["message"]
        inv["finished_at"] = _iso(_utcnow())
        inv["updated_at"] = _iso(_utcnow())
        _save("tool_requests.json", tool_requests)
        _save("api_keys.json", api_keys)
        return qerr
    _save("api_keys.json", api_keys)

    # Filter only rows for this api_key_id
    rows = [r for r in tool_requests if r.get("api_key_id") == api_key.get("id")]

    if tool_name is not None:
        rows = [r for r in rows if r.get("tool_name") == tool_name]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if youtube_video_id is not None:
        rows = [r for r in rows if r.get("resolved_youtube_video_id") == youtube_video_id]
    if youtube_channel_id is not None:
        rows = [r for r in rows if r.get("resolved_youtube_channel_id") == youtube_channel_id]
    if ca is not None:
        rows = [r for r in rows if (_parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)) >= ca]
    if cb is not None:
        rows = [r for r in rows if (_parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)) <= cb]

    # Sort newest-first by created_at then id
    def _sort_key(r):
        return (_parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), r.get("id") or "")
    rows.sort(key=_sort_key, reverse=True)

    start_index = 0
    if cursor:
        # cursor is last seen tool_requests.id
        for i, r in enumerate(rows):
            if r.get("id") == cursor:
                start_index = i + 1
                break

    page = rows[start_index:start_index + limit]
    has_more = start_index + limit < len(rows)
    next_cursor = page[-1].get("id") if has_more and page else None

    out = {
        "tool_requests": page,
        "next_cursor": next_cursor,
        "has_more": has_more,
        "total": len(rows),
    }

    inv["status"] = "succeeded"
    inv["output"] = {"returned": len(page), "has_more": has_more, "next_cursor": next_cursor, "total": len(rows)}
    inv["finished_at"] = _iso(_utcnow())
    inv["updated_at"] = _iso(_utcnow())
    _save("tool_requests.json", tool_requests)

    return {"data": out, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

def get_tool_request(id, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0489000" if __import__("os").path.isdir("./environment_mix/0489000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    _CROCK = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid():
        ms = int(time.time() * 1000)
        rnd = int.from_bytes(os.urandom(10), "big")
        v = (ms << 80) | rnd
        out = []
        for _ in range(26):
            out.append(_CROCK[v & 31])
            v >>= 5
        return "".join(reversed(out))

    def _new_id(prefix):
        return f"{prefix}_{_ulid()}"

    def _reset_window_if_needed(k, now):
        ws = _parse_dt(k.get("daily_window_start_at"))
        if ws is None or ws.astimezone(datetime.timezone.utc).date() != now.date():
            k["daily_window_start_at"] = _iso(datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc))
            k["daily_request_count"] = 0

    def _select_key_for_call(api_keys, now):
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            _reset_window_if_needed(k, now)
            limit = k.get("daily_request_limit")
            count = k.get("daily_request_count", 0)
            if not isinstance(limit, int) or limit < 0:
                continue
            if not isinstance(count, int) or count < 0:
                continue
            if limit != 0 and count + 1 > limit:
                continue
            return k
        return None

    t0 = time.time()
    now = _utcnow()

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    api_keys = _load("api_keys.json")
    tool_requests = _load("tool_requests.json")

    api_key = _select_key_for_call(api_keys, now)
    if api_key is None:
        return _err("UNAUTHORIZED", "No active API key available for this request")

    # Create an audit row for this invocation (every tool invocation must create tool_requests row)
    audit_id = _new_id("ytins_req")
    tr_audit = {
        "id": audit_id,
        "api_key_id": api_key.get("id"),
        "tool_name": "get_tool_request",
        "status": "running",
        "input": {"id": id},
        "resolved_youtube_video_id": None,
        "resolved_youtube_channel_id": None,
        "video_id": None,
        "channel_id": None,
        "output": None,
        "error_message": None,
        "upstream_provider": "other",
        "started_at": _iso(now),
        "finished_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    # tool_name enum in schema doesn't include get_tool_request; still we must persist calls.
    # We'll store it anyway to satisfy business rule; real stores might allow additional tool names.
    tool_requests.append(tr_audit)
    _save("tool_requests.json", tool_requests)

    if api_key.get("status") != "active":
        tr_audit["status"] = "failed"
        tr_audit["error_message"] = "API key is not active"
        tr_audit["finished_at"] = _iso(_utcnow())
        tr_audit["updated_at"] = tr_audit["finished_at"]
        _save("tool_requests.json", tool_requests)
        return _err("UNAUTHORIZED", "API key is not active", tool_request_id=audit_id)

    # Quota for accepted invocation
    _reset_window_if_needed(api_key, now)
    limit = api_key.get("daily_request_limit", 0)
    count = api_key.get("daily_request_count", 0)
    if isinstance(limit, int) and limit > 0 and isinstance(count, int) and count + 1 > limit:
        tr_audit["status"] = "failed"
        tr_audit["error_message"] = "Daily request quota exceeded"
        tr_audit["finished_at"] = _iso(_utcnow())
        tr_audit["updated_at"] = tr_audit["finished_at"]
        _save("tool_requests.json", tool_requests)
        _save("api_keys.json", api_keys)
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded", tool_request_id=audit_id)

    api_key["daily_request_count"] = int(count) + 1
    api_key["last_used_at"] = _iso(_utcnow())
    api_key["updated_at"] = api_key["last_used_at"]
    _save("api_keys.json", api_keys)

    # Enforce ownership: must belong to calling key
    target = None
    for r in tool_requests:
        if isinstance(r, dict) and r.get("id") == id:
            target = r
            break

    if target is None or target.get("api_key_id") != api_key.get("id"):
        tr_audit["status"] = "failed"
        tr_audit["error_message"] = "Tool request not found or not owned by this API key"
        tr_audit["finished_at"] = _iso(_utcnow())
        tr_audit["updated_at"] = tr_audit["finished_at"]
        _save("tool_requests.json", tool_requests)
        return _err("NOT_FOUND", "Tool request not found", tool_request_id=audit_id)

    tr_audit["status"] = "succeeded"
    tr_audit["output"] = {"tool_request": target}
    tr_audit["finished_at"] = _iso(_utcnow())
    tr_audit["updated_at"] = tr_audit["finished_at"]
    _save("tool_requests.json", tool_requests)

    return {
        "tool_request_id": audit_id,
        "tool_request": target,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)},
    }

def get_video(id=None, youtube_video_id=None, **_extra):
