            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str): return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    _CROCK = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid():
        ms = int(time.time() * 1000)
        t = ms
        out = []
        for _ in range(10):
            out.append(_CROCK[t & 31])
            t //= 32
        out.reverse()
        for _ in range(16):
            out.append(_CROCK[random.getrandbits(5)])
        return "".join(out)

    api_keys = _load("api_keys.json")
    videos = _load("videos.json")
    tool_requests = _load("tool_requests.json")

    # Ambient auth: select key that can serve
    def _select_key_for_call():
        for k in api_keys:
            if k.get("status") != "active":
                continue
            limit = k.get("daily_request_limit")
            if not isinstance(limit, int) or limit < 0:
                continue
            ws = _parse_dt(k.get("daily_window_start_at"))
            if ws is None or ws.date() != now.date():
                return k
            used = k.get("daily_request_count")
            if not isinstance(used, int) or used < 0:
                continue
            if limit > 0 and used >= limit:
                continue
            return k
        return None

    def _log(api_key_id, status, payload, output=None, error_message=None):
        tr = {
            "id": _ulid(),
            "api_key_id": api_key_id,
            "tool_name": "get_video",
            "status": status,
            "input": payload if isinstance(payload, dict) else {},
            "resolved_youtube_video_id": payload.get("youtube_video_id") if isinstance(payload, dict) else None,
            "resolved_youtube_channel_id": None,
            "video_id": None,
            "channel_id": None,
            "output": output,
            "error_message": error_message,
            "upstream_provider": None,
            "started_at": _iso(now),
            "finished_at": _iso(datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)),
            "created_at": _iso(now),
            "updated_at": _iso(datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)),
        }
        tool_requests.append(tr)
        _save("tool_requests.json", tool_requests)

    payload = {}
    if id is not None: payload["id"] = id
    if youtube_video_id is not None: payload["youtube_video_id"] = youtube_video_id

    # Validate identifiers
    if (id is None or (isinstance(id, str) and not id.strip()) or not isinstance(id, str)) and youtube_video_id is None:
