    if youtube_video_id is not None:
        if not isinstance(youtube_video_id, str) or not youtube_video_id.strip():
            k = _select_key_for_call()
            if k:
                _log(k["id"], "failed", payload, None, "VALIDATION_ERROR: youtube_video_id must be a non-empty string")
            return _err("VALIDATION_ERROR", "youtube_video_id must be a non-empty string")
        # soft validation of typical 11-char ID
        if not re.fullmatch(r"[A-Za-z0-9_-]{6,20}", youtube_video_id.strip()):
            k = _select_key_for_call()
            if k:
                _log(k["id"], "failed", payload, None, "VALIDATION_ERROR: youtube_video_id format invalid")
            return _err("VALIDATION_ERROR", "youtube_video_id format invalid")

    api_key = _select_key_for_call()
    if api_key is None:
        return _err("UNAUTHORIZED", "No active API key available for this call")
    if api_key.get("status") != "active":
        _log(api_key.get("id"), "failed", payload, None, "FORBIDDEN: API key is not active")
        return _err("UNAUTHORIZED", "API key is not active")

    # Quota enforcement and increment
    limit = api_key.get("daily_request_limit", 0)
    if not isinstance(limit, int) or limit < 0:
        _log(api_key["id"], "failed", payload, None, "VALIDATION_ERROR: API key limit misconfigured")
        return _err("UNAUTHORIZED", "API key not permitted")

    ws = _parse_dt(api_key.get("daily_window_start_at"))
    if ws is None or ws.date() != now.date():
        api_key["daily_window_start_at"] = _iso(now)
        api_key["daily_request_count"] = 0
    used = api_key.get("daily_request_count", 0)
    if not isinstance(used, int) or used < 0:
        _log(api_key["id"], "failed", payload, None, "VALIDATION_ERROR: API key usage misconfigured")
        return _err("UNAUTHORIZED", "API key not permitted")
    if limit > 0 and used + 1 > limit:
        _log(api_key["id"], "failed", payload, None, "QUOTA_EXCEEDED: daily request limit exceeded")
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded", limit=limit, used=used)

    api_key["daily_request_count"] = used + 1
    api_key["last_used_at"] = _iso(now)
    api_key["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    # Fetch video
    row = None
    if youtube_video_id is not None:
        yid = youtube_video_id.strip()
        for v in videos:
            if v.get("youtube_video_id") == yid:
                row = v
                break
    if row is None and id is not None:
        vid = id.strip()
        for v in videos:
            if v.get("id") == vid:
                row = v
                break

    if row is None:
        _log(api_key["id"], "failed", payload, None, "NOT_FOUND: video not found")
        return _err("NOT_FOUND", "Video not found")

    out = {"video": row}
    _log(api_key["id"], "succeeded", payload, out, None)
    return out

