            "output": output,
            "error_message": error_message,
            "upstream_provider": None,
            "started_at": _iso(now),
            "finished_at": _iso(datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)),
            "created_at": _iso(now),
            "updated_at": _iso(datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)),
        }
        tool_requests.append(tr)
        _save("tool_requests.json", tool_requests)

    payload = {}
    if id is not None: payload["id"] = id
    if youtube_channel_id is not None: payload["youtube_channel_id"] = youtube_channel_id
    if handle is not None: payload["handle"] = handle

    if id is None and youtube_channel_id is None and handle is None:
        k = _select_key_for_call()
        if k:
            _log(k["id"], "failed", payload, None, "VALIDATION_ERROR: Provide id, youtube_channel_id, or handle")
        return _err("VALIDATION_ERROR", "Provide one of: id, youtube_channel_id, handle")

    if id is not None and (not isinstance(id, str) or not id.strip()):
        k = _select_key_for_call()
        if k:
            _log(k["id"], "failed", payload, None, "VALIDATION_ERROR: id must be a non-empty string")
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    if youtube_channel_id is not None:
        if not isinstance(youtube_channel_id, str) or not youtube_channel_id.strip():
            k = _select_key_for_call()
            if k:
                _log(k["id"], "failed", payload, None, "VALIDATION_ERROR: youtube_channel_id must be a non-empty string")
            return _err("VALIDATION_ERROR", "youtube_channel_id must be a non-empty string")
        if not re.fullmatch(r"UC[A-Za-z0-9_-]{10,40}", youtube_channel_id.strip()):
            k = _select_key_for_call()
            if k:
                _log(k["id"], "failed", payload, None, "VALIDATION_ERROR: youtube_channel_id format invalid")
            return _err("VALIDATION_ERROR", "youtube_channel_id format invalid")

    if handle is not None:
        if not isinstance(handle, str) or not handle.strip():
            k = _select_key_for_call()
            if k:
                _log(k["id"], "failed", payload, None, "VALIDATION_ERROR: handle must be a non-empty string")
            return _err("VALIDATION_ERROR", "handle must be a non-empty string")
        h = handle.strip()
        if not h.startswith("@"):
            # allow without @ but normalize for lookup
            h = "@" + h
        payload["handle"] = h

    api_key = _select_key_for_call()
    if api_key is None:
        return _err("UNAUTHORIZED", "No active API key available for this call")
    if api_key.get("status") != "active":
        _log(api_key.get("id"), "failed", payload, None, "FORBIDDEN: API key is not active")
        return _err("UNAUTHORIZED", "API key is not active")

    # quota increment
    limit = api_key.get("daily_request_limit", 0)
    if not isinstance(limit, int) or limit < 0:
        _log(api_key["id"], "failed", payload, None, "VALIDATION_ERROR: API key limit misconfigured")
        return _err("UNAUTHORIZED", "API key not permitted")

    ws = _parse_dt(api_key.get("daily_window_start_at"))
    if ws is None or ws.date() != now.date():
        api_key["daily_window_start_at"] = _iso(now)
        api_key["daily_request_count"] = 0
    used = api_key.get("daily_request_count", 0)
    if not isinstance(used, int) or used < 0:
        _log(api_key["id"], "failed", payload, None, "VALIDATION_ERROR: API key usage misconfigured")
        return _err("UNAUTHORIZED", "API key not permitted")
    if limit > 0 and used + 1 > limit:
        _log(api_key["id"], "failed", payload, None, "QUOTA_EXCEEDED: daily request limit exceeded")
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded", limit=limit, used=used)

    api_key["daily_request_count"] = used + 1
    api_key["last_used_at"] = _iso(now)
    api_key["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    row = None
    if youtube_channel_id is not None:
        ycid = youtube_channel_id.strip()
        for c in channels:
            if c.get("youtube_channel_id") == ycid:
                row = c
                break
    if row is None and handle is not None:
        h = payload["handle"]
        for c in channels:
            if isinstance(c.get("handle"), str) and c.get("handle") == h:
                row = c
                break
    if row is None and id is not None:
        cid = id.strip()
        for c in channels:
            if c.get("id") == cid:
                row = c
                break

    if row is None:
        _log(api_key["id"], "failed", payload, None, "NOT_FOUND: channel not found")
        return _err("NOT_FOUND", "Channel not found")

    out = {"channel": row}
    _log(api_key["id"], "succeeded", payload, out, None)
    return out

def refresh_transcript(id=None, video_id=None, language=None, is_auto_generated=None, source=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0489000" if __import__("os").path.isdir("./environment_mix/0489000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    _CROCK = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid():
        ms = int(time.time() * 1000)
        rnd = int.from_bytes(os.urandom(10), "big")
        v = (ms << 80) | rnd
        out = []
        for _ in range(26):
            out.append(_CROCK[v & 31])
            v >>= 5
        return "".join(reversed(out))

    def _new_id(prefix):
        return f"{prefix}_{_ulid()}"

    def _reset_window_if_needed(k, now):
        ws = _parse_dt(k.get("daily_window_start_at"))
        if ws is None or ws.astimezone(datetime.timezone.utc).date() != now.date():
            k["daily_window_start_at"] = _iso(datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc))
            k["daily_request_count"] = 0

    def _select_key_for_call(api_keys, now):
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            _reset_window_if_needed(k, now)
            limit = k.get("daily_request_limit")
            count = k.get("daily_request_count", 0)
            if not isinstance(limit, int) or limit < 0:
                continue
            if not isinstance(count, int) or count < 0:
                continue
            if limit != 0 and count + 1 > limit:
                continue
            return k
        return None

    t0 = time.time()
    now = _utcnow()

    # Validate identifier: either id OR (video_id + language + is_auto_generated + source)
    if id is None and video_id is None:
        return _err("VALIDATION_ERROR", "Provide either id or video_id with language, is_auto_generated, and source")
    if id is not None and (not isinstance(id, str) or not id.strip()):
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    if video_id is not None and (not isinstance(video_id, str) or not video_id.strip()):
        return _err("VALIDATION_ERROR", "video_id must be a non-empty string")
    if video_id is not None:
        if not isinstance(language, str) or not language.strip():
            return _err("VALIDATION_ERROR", "language is required when using video_id")
        if not isinstance(is_auto_generated, bool):
            return _err("VALIDATION_ERROR", "is_auto_generated is required and must be boolean when using video_id")
        if not isinstance(source, str) or not source.strip():
            return _err("VALIDATION_ERROR", "source is required when using video_id")
        # Tool enum says uploaded, but datastore uses manual_upload. Accept both and normalize.
        if source not in ("youtube", "third_party", "uploaded", "manual_upload"):
            return _err("VALIDATION_ERROR", "source must be one of youtube, third_party, uploaded")
        if source == "uploaded":
            source_norm = "manual_upload"
        else:
            source_norm = source
    else:
        source_norm = None

    api_keys = _load("api_keys.json")
    videos = _load("videos.json")
    transcripts = _load("transcripts.json")
    tool_requests = _load("tool_requests.json")

    api_key = _select_key_for_call(api_keys, now)
    if api_key is None:
        return _err("UNAUTHORIZED", "No active API key available for this request")

    # Create tool request
    req_id = _new_id("ytins_req")
    tr = {
        "id": req_id,
        "api_key_id": api_key.get("id"),
        "tool_name": "get_youtube_transcript",
        "status": "running",
        "input": {"id": id, "video_id": video_id, "language": language, "is_auto_generated": is_auto_generated, "source": source},
        "resolved_youtube_video_id": None,
        "resolved_youtube_channel_id": None,
        "video_id": video_id if isinstance(video_id, str) else None,
        "channel_id": None,
        "output": None,
        "error_message": None,
        "upstream_provider": "other",
        "started_at": _iso(now),
        "finished_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    tool_requests.append(tr)
    _save("tool_requests.json", tool_requests)

    if api_key.get("status") != "active":
        tr["status"] = "failed"
        tr["error_message"] = "API key is not active"
        tr["finished_at"] = _iso(_utcnow())
        tr["updated_at"] = tr["finished_at"]
        _save("tool_requests.json", tool_requests)
        return _err("UNAUTHORIZED", "API key is not active", tool_request_id=req_id)

    # Quota
    _reset_window_if_needed(api_key, now)
    limit = api_key.get("daily_request_limit", 0)
    count = api_key.get("daily_request_count", 0)
    if isinstance(limit, int) and limit > 0 and isinstance(count, int) and count + 1 > limit:
        tr["status"] = "failed"
        tr["error_message"] = "Daily request quota exceeded"
        tr["finished_at"] = _iso(_utcnow())
        tr["updated_at"] = tr["finished_at"]
        _save("tool_requests.json", tool_requests)
        _save("api_keys.json", api_keys)
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded", tool_request_id=req_id)

    api_key["daily_request_count"] = int(count) + 1
    api_key["last_used_at"] = _iso(_utcnow())
    api_key["updated_at"] = api_key["last_used_at"]
    _save("api_keys.json", api_keys)

    # Find transcript
    target = None
    if id is not None:
        for trow in transcripts:
            if isinstance(trow, dict) and trow.get("id") == id:
                target = trow
                break
    else:
        # Validate FK existence of video_id
        vrow = None
        for v in videos:
            if isinstance(v, dict) and v.get("id") == video_id:
                vrow = v
                break
        if vrow is None:
            tr["status"] = "failed"
            tr["error_message"] = "video_id does not reference an existing video"
            tr["finished_at"] = _iso(_utcnow())
            tr["updated_at"] = tr["finished_at"]
            _save("tool_requests.json", tool_requests)
            return _err("NOT_FOUND", "Video not found", tool_request_id=req_id)

        for trow in transcripts:
            if not isinstance(trow, dict):
                continue
            if trow.get("video_id") != video_id:
                continue
            if (trow.get("language") or "") != language:
                continue
            if bool(trow.get("is_auto_generated")) != bool(is_auto_generated):
                continue
            if trow.get("source") != source_norm:
                continue
            target = trow
            break

    if target is None:
        tr["status"] = "failed"
        tr["error_message"] = "Transcript not found for provided identifier"
        tr["finished_at"] = _iso(_utcnow())
        tr["updated_at"] = tr["finished_at"]
        _save("tool_requests.json", tool_requests)
        return _err("NOT_FOUND", "Transcript not found", tool_request_id=req_id)

    # Enforce transition: cannot refresh if already fetching => CONFLICT
    if target.get("status") == "fetching":
        tr["status"] = "failed"
        tr["error_message"] = "Transcript already fetching"
        tr["finished_at"] = _iso(_utcnow())
        tr["updated_at"] = tr["finished_at"]
        _save("tool_requests.json", tool_requests)
        return _err("CONFLICT", "Transcript is already in fetching", tool_request_id=req_id, transcript_id=target.get("id"))

    # Legal transitions: available/unavailable/error -> fetching
    if target.get("status") not in ("available", "unavailable", "error"):
        tr["status"] = "failed"
        tr["error_message"] = "Invalid transcript state transition"
        tr["finished_at"] = _iso(_utcnow())
        tr["updated_at"] = tr["finished_at"]
        _save("tool_requests.json", tool_requests)
        return _err("INVALID_TRANSITION", "Transcript can only be refreshed from available/unavailable/error", tool_request_id=req_id, from_status=target.get("status"), to_status="fetching")

    # Mutate transcript
    target["status"] = "fetching"
    target["error_code"] = None
    target["error_message"] = None
    target["updated_at"] = _iso(_utcnow())
    # do not set fetched_at here (only on successful fetch)
    _save("transcripts.json", transcripts)

    tr["status"] = "succeeded"
    tr["output"] = {"transcript": target}
    tr["finished_at"] = _iso(_utcnow())
    tr["updated_at"] = tr["finished_at"]
    tr["video_id"] = target.get("video_id")
    _save("tool_requests.json", tool_requests)

    return {
        "tool_request_id": req_id,
        "transcript": target,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)},
    }
